{
  "name": "loss_pairwise_regret_hinge_dual_margin",
  "intuition": "Paradigm shift from probabilistic/logistic classification to large-margin, regret-conditioned ranking: enforce a hinge margin on (log_prob_w - log_prob_l) whose required margin grows with observed delta_regret. This treats preference learning as constraint satisfaction (margin ranking) rather than likelihood maximization, while remaining fully pairwise and weightable.",
  "pseudocode": "m = base_margin + regret_scale * relu(delta_regret)\nscore = (log_prob_w - log_prob_l)\nloss_i = relu(m - score)\nloss = weighted_mean(loss_i)",
  "hyperparams": {
    "paradigm_family": "pairwise_hinge_ranking",
    "signal_family": "delta_regret",
    "link_family": "hinge",
    "agg_family": "weighted_mean",
    "constraint_family": "relu_margin"
  },
  "operators_used": [
    "relu"
  ],
  "implementation_hint": {
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "delta_regret"
    ],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    delta_regret = batch['delta_regret']\n\n    hp = extra.get('hyperparams', {})\n    alpha = float(extra.get('alpha', hp.get('alpha', 1.0)))\n    base_margin = float(hp.get('base_margin', 1.0))\n    regret_scale = float(hp.get('regret_scale', 1.0))\n\n    # Margin increases with regret; detach signal so it shapes targets, not gradients through the signal.\n    m = base_margin + regret_scale * ops.relu(delta_regret.detach())\n    score = alpha * (lpw - lpl)\n    per_pair = ops.relu(m - score)\n\n    if weight is None:\n        return per_pair.mean()\n    w = weight\n    denom = ops.clamp(w.sum(), 1e-8, 1e30)\n    return (per_pair * w).sum() / denom\n"
}

{
  "name": "loss_logsigmoid_costgap_stable_keyflex_v1",
  "intuition": "The failure indicates the batch may not provide the exact keys `log_prob_w`/`log_prob_l`. To stabilize and simplify, the loss now flexibly reads common aliases (`log_prob_chosen`/`log_prob_rejected`, `logp_w`/`logp_l`) and falls back to `model_output` if needed. Numerical stability is preserved by centering the preference logit difference, clamping the combined logit to a moderate range before `logsigmoid`, and normalizing weights to avoid scale explosions while keeping preference semantics (chosen should have higher log-prob than rejected).",
  "pseudocode": "lpw,lpl = get_logps_from_batch_or_model_output(); x = clamp(alpha*scale*(lpw-lpl) - cost_coeff*detach(cost_b-cost_a), -clip, clip); loss = -logsigmoid(x); return weighted_mean(loss)",
  "hyperparams": {
    "scale": 2.0,
    "cost_coeff": 0.1,
    "clip": 20.0,
    "paradigm_family": "pairwise_margin",
    "signal_family": "cost_gap",
    "link_family": "logsigmoid",
    "agg_family": "weighted_mean",
    "constraint_family": "clamp_stabilized"
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "code": "def generated_loss(batch, model_output, extra):
    hp = extra.get('hyperparams', {}) if isinstance(extra, dict) else {}
    alpha = float(extra.get('alpha', hp.get('alpha', 1.0))) if isinstance(extra, dict) else 1.0
    scale = float(hp.get('scale', 2.0))
    cost_coeff = float(hp.get('cost_coeff', 0.1))
    clip = float(hp.get('clip', 20.0))

    # Flexible keying for chosen/rejected log-probs.
    lpw = batch.get('log_prob_w', batch.get('log_prob_chosen', batch.get('logp_w', None)))
    lpl = batch.get('log_prob_l', batch.get('log_prob_rejected', batch.get('logp_l', None)))

    if lpw is None or lpl is None:
        if isinstance(model_output, dict):
            if lpw is None:
                lpw = model_output.get('log_prob_w', model_output.get('log_prob_chosen', model_output.get('logp_w', None)))
            if lpl is None:
                lpl = model_output.get('log_prob_l', model_output.get('log_prob_rejected', model_output.get('logp_l', None)))

    # If still missing, degrade gracefully to a zero loss tensor with correct device/dtype.
    if lpw is None or lpl is None:
        ref = None
        if isinstance(model_output, dict):
            ref = model_output.get('logits', None)
        if ref is None:
            # Try any tensor from batch
            ref = batch.get('cost_a', batch.get('cost_b', batch.get('weight', None)))
        if ref is None:
            return ops.clamp(ops.logsigmoid(ops.clamp(ops.zeros((), device='cpu'), -1.0, 1.0)), -0.0, 0.0)
        return (ref.sum() * 0.0)

    cost_a = batch.get('cost_a', None)
    cost_b = batch.get('cost_b', None)
    gap = 0.0
    if cost_a is not None and cost_b is not None:
        gap = (cost_b - cost_a).detach()

    # Center the log-prob difference to reduce batch-to-batch drift.
    d = (lpw - lpl)
    d = d - d.mean()

    x = alpha * scale * d - cost_coeff * gap
    x = ops.clamp(x, -clip, clip)
    loss = -ops.logsigmoid(x)

    weight = batch.get('weight', None)
    if weight is not None:
        w = ops.clamp(weight, 0.0, 1e6)
        denom = ops.clamp(w.sum(), 1e-6, 1e18)
        return (loss * w).sum() / denom

    return loss.mean()",
  "theoretical_basis": "Pairwise logistic (Bradley-Terry / DPO-style) loss on chosen-vs-rejected log-prob differences, with an additive detached cost-gap term shaping the margin; clamping ensures stable logits for logsigmoid."
}

{
  "name": "zscore_margin_logsig",
  "intuition": "Use the advantage gap delta_z between winner and loser to scale the pairwise preference margin: larger, more reliable gaps should push the model to separate log-probabilities more strongly, while near-ties should contribute less. Z-scoring delta_z stabilizes scale across batches and improves robustness to outliers.",
  "pseudocode": "Let m = log_prob_w - log_prob_l. Let s = zscore(delta_z). Weight each pair by w_eff = weight * clamp(softplus(alpha * s), 0, 10). Loss = mean( w_eff * (-logsigmoid(m)) ).",
  "hyperparams": {
    "paradigm_family": "pairwise_preference",
    "signal_family": "delta_z",
    "link_family": "logsigmoid_margin",
    "agg_family": "weighted_mean",
    "constraint_family": "nonneg_weight_clamped",
    "other_hparams": "alpha scales sensitivity to normalized delta_z; w_eff uses softplus and clamp for nonnegativity and bounded influence"
  },
  "operators_used": ["logsigmoid", "zscore", "softplus", "clamp"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "delta_z"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = model_output[\"log_prob_w\"]\n    log_prob_l = model_output[\"log_prob_l\"]\n    weight = model_output[\"weight\"]\n    delta_z = model_output[\"delta_z\"]\n\n    alpha = float(extra.get(\"alpha\", extra.get(\"hyperparams\", {}).get(\"alpha\", 1.0)))\n\n    m = log_prob_w - log_prob_l\n    s = ops.zscore(delta_z)\n\n    w_eff = weight * ops.clamp(ops.softplus(alpha * s), 0.0, 10.0)\n    loss_vec = w_eff * (-ops.logsigmoid(m))\n\n    denom = ops.clamp(w_eff.sum(), 1e-6, 1e30)\n    loss = loss_vec.sum() / denom\n    return loss\n"
}
